{
  "query": "query restaurant($id:String){ restaurant(id:$id){ _id name slug isActive isAvailable address deliveryTime minimumOrder logo commissionRate tax currentWalletAmount totalWalletAmount openingTimes { day times { startTime endTime } } bussinessDetails { bankName accountNumber } } }",
  "variables": {
    "id": "{{restaurantId}}"
  }
}

{
  "query": "query { configuration { _id currency currencySymbol deliveryRate termsAndConditions privacyPolicy skipEmailVerification skipMobileVerification currencySymbol googleMapsApiKey } }",
  "variables": {}
}

{
  "query": "mutation editRestaurant($restaurant:RestaurantProfileInput!){ editRestaurant(restaurant:$restaurant){ _id name slug isActive isAvailable address deliveryTime minimumOrder } }",
  "variables": {
    "restaurant": {
      "_id": "{{restaurantId}}",
      "name": "Sample Restaurant",
      "phone": "+15550003333",
      "address": "123 Main St, San Francisco, CA",
      "deliveryTime": 30,
      "minimumOrder": 10,
      "isAvailable": true
    }
  }
}

{
  "query": "query($id:ID!){ getRestaurantDeliveryZoneInfo(id:$id){ boundType address city postCode circleBounds { radius } location { coordinates } } }",
  "variables": {
    "id": "{{restaurantId}}"
  }
}

{
  "query": "query { restaurantOrders { _id orderId orderStatus paymentMethod paymentStatus orderAmount paidAmount isActive isPickedUp createdAt restaurant { _id name } user { _id name phone } rider { _id name } items { _id title quantity price } } }",
  "variables": {}
}

{
  "query": "query($restaurant:String!,$page:Int,$rows:Int,$search:String,$orderStatus:[String]){ ordersByRestId(restaurant:$restaurant,page:$page,rows:$rows,search:$search,orderStatus:$orderStatus){ totalCount orders { _id orderId orderStatus paymentMethod paymentStatus orderAmount paidAmount isActive isPickedUp createdAt restaurant { _id name } user { _id name phone } rider { _id name } items { _id title quantity price } } } }",
  "variables": {
    "restaurant": "{{restaurantId}}",
    "page": 1,
    "rows": 10,
    "search": "",
    "orderStatus": []
  }
}

{
  "query": "query($restaurantId:String,$page:Int,$rowsPerPage:Int){ getActiveOrders(restaurantId:$restaurantId,page:$page,rowsPerPage:$rowsPerPage){ totalCount orders { _id orderId orderStatus paymentMethod paymentStatus orderAmount paidAmount isActive isPickedUp createdAt restaurant { _id name } user { _id name phone } rider { _id name } items { _id title quantity price } } } }",
  "variables": {
    "restaurantId": "{{restaurantId}}",
    "page": 1,
    "rowsPerPage": 10
  }
}

{
  "query": "query order($id:String!){ order(id:$id){ _id orderId orderStatus paymentMethod paymentStatus orderAmount paidAmount isActive isPickedUp createdAt restaurant { _id name } user { _id name phone } rider { _id name } items { _id title quantity price } } }",
  "variables": {
    "id": "{{orderId}}"
  }
}

{
  "query": "query orderDetails($id:String!){ orderDetails(id:$id){ _id orderId orderStatus paymentMethod paymentStatus orderAmount paidAmount isActive isPickedUp createdAt restaurant { _id name } user { _id name phone } rider { _id name } items { _id title quantity price } deliveryAddress { deliveryAddress } } }",
  "variables": {
    "id": "{{orderId}}"
  }
}

{
  "query": "mutation cancelOrder($_id:String!,$reason:String!){ cancelOrder(_id:$_id,reason:$reason){ _id orderStatus reason cancelledAt } }",
  "variables": {
    "_id": "{{orderId}}",
    "reason": "Out of stock"
  }
}

{
  "query": "query($restaurantId:String!,$page:Int,$limit:Int,$search:String){ restaurantAddonsPaginated(restaurantId:$restaurantId,page:$page,limit:$limit,search:$search){ totalCount data { _id title description quantityMinimum quantityMaximum options { _id title price } } } }",
  "variables": {
    "restaurantId": "{{restaurantId}}",
    "page": 1,
    "limit": 10,
    "search": ""
  }
}

{
  "query": "query popularFoodItems($restaurantId:String!){ popularFoodItems(restaurantId:$restaurantId){ _id title description image isActive isOutOfStock variations { _id title price } } }",
  "variables": {
    "restaurantId": "{{restaurantId}}"
  }
}

{
  "query": "mutation createAddon($addonInput:AddonInput!){ createAddon(addonInput:$addonInput){ _id title description quantityMinimum quantityMaximum options { _id title price } } }",
  "variables": {
    "addonInput": {
      "restaurant": "{{restaurantId}}",
      "title": "QA Addon",
      "quantityMinimum": 0,
      "quantityMaximum": 2,
      "options": [
        {
          "title": "Extra",
          "price": 1
        }
      ]
    }
  }
}

{
  "query": "mutation editAddon($addonInput:AddonInput!){ editAddon(addonInput:$addonInput){ _id title description quantityMinimum quantityMaximum options { _id title price } } }",
  "variables": {
    "addonInput": {
      "_id": "{{addonId}}",
      "restaurant": "{{restaurantId}}",
      "title": "Extra Toppings",
      "quantityMinimum": 0,
      "quantityMaximum": 3
    }
  }
}

{
  "query": "query restaurantCoupons($restaurantId:String!){ restaurantCoupons(restaurantId:$restaurantId){ _id title discount enabled lifeTimeActive startDate endDate } }",
  "variables": {
    "restaurantId": "{{restaurantId}}"
  }
}

{
  "query": "query($restaurantId:String!,$page:Int,$limit:Int){ restaurantCouponsPaginated(restaurantId:$restaurantId,page:$page,limit:$limit){ totalCount data { _id title discount enabled lifeTimeActive startDate endDate } } }",
  "variables": {
    "restaurantId": "{{restaurantId}}",
    "page": 1,
    "limit": 10
  }
}

{
  "query": "mutation($restaurantId:ID!,$couponInput:CouponInput!){ createRestaurantCoupon(restaurantId:$restaurantId,couponInput:$couponInput){ _id title discount enabled lifeTimeActive startDate endDate } }",
  "variables": {
    "restaurantId": "{{restaurantId}}",
    "couponInput": {
      "title": "SQA1787891593987",
      "discount": 5,
      "enabled": true
    }
  }
}

{
  "query": "mutation($restaurantId:ID!,$couponInput:CouponInput!){ editRestaurantCoupon(restaurantId:$restaurantId,couponInput:$couponInput){ _id title discount enabled lifeTimeActive startDate endDate } }",
  "variables": {
    "restaurantId": "{{restaurantId}}",
    "couponInput": {
      "_id": "{{couponId}}",
      "title": "BURGER5",
      "discount": 5,
      "enabled": true
    }
  }
}

{
  "query": "query($userType:UserTypeEnum,$userId:String,$pagination:MoneyPaginationInput){ transactionHistory(userType:$userType,userId:$userId,pagination:$pagination){ pagination { total } data { _id transactionId status amountTransferred } } }",
  "variables": {
    "userType": "STORE",
    "userId": "{{restaurantId}}",
    "pagination": {
      "pageSize": 10,
      "pageNo": 1
    }
  }
}

{
  "query": "query($userType:UserTypeEnum,$pagination:MoneyPaginationInput){ earnings(userType:$userType,pagination:$pagination){ success pagination { total } data { grandTotalEarnings { storeTotal } earnings { _id orderId } } } }",
  "variables": {
    "userType": "STORE",
    "pagination": {
      "pageSize": 10,
      "pageNo": 1
    }
  }
}

{
  "query": "query reviewsByRestaurant($restaurant:String!){ reviewsByRestaurant(restaurant:$restaurant){ reviews { _id rating description comments isActive createdAt order { user { _id name } } } } }",
  "variables": {
    "restaurant": "{{restaurantId}}"
  }
}

{
  "query": "mutation($ticketInput:SupportTicketInput!){ createSupportTicket(ticketInput:$ticketInput){ _id title description status category orderId createdAt user { _id name userType } } }",
  "variables": {
    "ticketInput": {
      "title": "Store issue",
      "description": "Printer not working",
      "category": "TECHNICAL",
      "userType": "VENDOR"
    }
  }
}

{
  "query": "query($input:SingleUserSupportTicketsInput!){ getSingleUserSupportTickets(input:$input){ docsCount tickets { _id title description status category orderId createdAt user { _id name userType } } } }",
  "variables": {
    "input": {
      "userId": "{{ownerId}}",
      "filters": {
        "page": 1,
        "limit": 10
      }
    }
  }
}

{
  "query": "query($input:TicketMessagesInput!){ getTicketMessages(input:$input){ docsCount messages { _id content senderType isRead ticket createdAt } } }",
  "variables": {
    "input": {
      "ticket": "{{ticketId}}",
      "page": 1,
      "limit": 20
    }
  }
}

{
  "query": "mutation($messageInput:MessageInput!){ createMessage(messageInput:$messageInput){ _id content senderType isRead ticket createdAt } }",
  "variables": {
    "messageInput": {
      "content": "Still broken",
      "ticket": "{{ticketId}}"
    }
  }
}

